{
  "probability": 0.95,
  "range_low": 0.90,
  "range_high": 0.98,
  "summary": [
    "Early 2026 pace shows 606 deaths by late February, suggesting a trajectory that could reach 1,000 by May if the trend continues.",
    "Historical patterns indicate Jan–May typically accounts for a substantial share of annual fatalities, making a 1,000-death by May scenario plausible.",
    "Weather, sea conditions, and SAR capacity could push fatalities up or down; recent incidents have raised risk but improved rescue capacity could dampen the trajectory.",
    "Reporting lags and data revisions may inflate observed totals later in the year, adding uncertainty to the near-term forecast."
  ],
  "confidence": "high",
  "narrative": "The analysis starts from a cautious anchor around 0.65 and updates it upward due to a notably lethal early 2026 pace and historical Jan–May concentration. While improvements in SAR capacity or adverse weather could alter the path, the balance of evidence supports a high probability that 1,000 deaths are recorded before May 2026, with a calibrated range of 0.90–0.98.",
  "justification": {
    "anchor": {
      "probability": 0.65,
      "basis": "Reference class uses Central Mediterranean annual tolls (~2,000–2,400 per year). The anchor of 0.65 reflects a cautious prior before applying updates from observed pace and historical patterns."
    },
    "factor_updates": [
      {
        "factor": "Pace of Mediterranean fatalities so far in 2026",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "606 deaths by February indicate a pace that could accumulate to reach or exceed 1,000 by May if it persists."
      },
      {
        "factor": "Jan–May concentration of annual toll",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Historical data suggest ~40–45% of annual tolls occur in Jan–May, increasing the plausibility of 1,000 deaths by May given current pace."
      },
      {
        "factor": "Weather/sea-state and rescue capacity in spring 2026",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Uncertain weather and SAR capacity could shift outcomes in either direction; no clear directional bias dominates."
      },
      {
        "factor": "Reporting lag and data revision risk",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Early-year undercounts may be corrected later, pushing observed totals higher and aligning with the 1,000-by-May target."
      },
      {
        "factor": "Search-and-rescue capacity and policy signals",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Improvements in SAR capacity could reduce fatalities, dampening the trajectory toward 1,000 by May."
      }
    ],
    "synthesis_rationale": "Starting from a 0.65 anchor, the combination of a strong recent pace and credible Jan–May concentration patterns supports a high posterior. The dampening from potential SAR improvements and the possibility of reporting lags introduce correlated uncertainty, but the overall calibration yields a 0.95 posterior with a 0.90–0.98 credible range."
  }
}

